# Monte Carlo check of the posterior probabilities of PosteriorProb()
#
# Run from the package root, after devtools::load_all() or
# library(OncoCohortSelect):
#   source("inst/validation/validate_posterior.R")
# Writes inst/validation/output/validate_posterior.csv and
# inst/validation/output/validate_posterior.md (generated, do not edit by hand).
#
# Each probability is compared with the proportion of 10^6 draws from the
# posterior distributions; PASS when the difference is within 4 Monte Carlo
# standard errors (plus 1e-5 for the quadrature). Run time: about a minute.

if (!exists("PosteriorProb")) library(OncoCohortSelect)
out_dir <- file.path("inst", "validation", "output")
dir.create(out_dir, showWarnings = FALSE, recursive = TRUE)
set.seed(20261022)
B <- 1e6

grid <- expand.grid(case = 1:6, higher = c(TRUE, FALSE), stringsAsFactors = FALSE)
pars <- list(
  list(measure = "rate", a = 18.5, b = 22.5, target = 0.4, time = NA, ar = NA, br = NA),
  list(measure = "surv", a = 20.5, b = 300, target = 0.6, time = 6, ar = NA, br = NA),
  list(measure = "rate", a = 18.5, b = 22.5, target = 0.1, time = NA, ar = 12.5, br = 28.5),
  list(measure = "rate", a = 0.5, b = 40.5, target = -0.05, time = NA, ar = 3.5, br = 37.5),
  list(measure = "surv", a = 20.5, b = 300, target = 0.05, time = 6, ar = 25.5, br = 280),
  list(measure = "hr", a = 20.5, b = 300, target = 0.8, time = NA, ar = 25.5, br = 280))

draw <- function(ms, a, b, n) {
  if (ms == "rate") stats::rbeta(n, a, b) else stats::rgamma(n, a, rate = b)
}
rows <- list()
for (i in seq_len(nrow(grid))) {
  q <- pars[[grid$case[i]]]
  hb <- grid$higher[i]
  two <- !is.na(q$ar)
  p <- PosteriorProb(q$measure, q$a, q$b, q$target,
                     time = if (is.na(q$time)) NULL else q$time,
                     a.ref = if (two) q$ar else NULL, b.ref = if (two) q$br else NULL,
                     higher.better = hb)
  x <- draw(q$measure, q$a, q$b, B)
  theta <- if (q$measure == "surv") exp(-q$time * x) else x
  if (!two) {
    ev <- if (hb) theta >= q$target else theta <= q$target
  } else {
    y <- draw(q$measure, q$ar, q$br, B)
    theta_r <- if (q$measure == "surv") exp(-q$time * y) else y
    if (q$measure == "hr") {
      ev <- if (hb) x / y <= q$target else x / y >= q$target
    } else {
      ev <- if (hb) theta - theta_r >= q$target else theta - theta_r <= q$target
    }
  }
  mc <- mean(ev)
  tol <- 4 * sqrt(max(mc * (1 - mc), 1e-12) / B) + 1e-5
  rows[[i]] <- data.frame(measure = q$measure, two.sample = two, higher.better = hb,
                          target = q$target, computed = p, monte_carlo = mc,
                          abs_diff = abs(p - mc), tolerance = tol,
                          judgment = if (abs(p - mc) <= tol) "PASS" else "FAIL",
                          stringsAsFactors = FALSE)
}
res <- do.call(rbind, rows)

# quadrature: 200 nodes against 2000 nodes for the cases with a reference group
conv <- vapply(pars[3:5], function(q) {
  p200 <- PosteriorProb(q$measure, q$a, q$b, q$target,
                        time = if (is.na(q$time)) NULL else q$time, a.ref = q$ar, b.ref = q$br)
  p2000 <- PosteriorProb(q$measure, q$a, q$b, q$target,
                         time = if (is.na(q$time)) NULL else q$time, a.ref = q$ar, b.ref = q$br,
                         n.nodes = 2000)
  abs(p200 - p2000)
}, numeric(1))
res <- rbind(res, data.frame(measure = "rate/surv", two.sample = TRUE, higher.better = TRUE,
                             target = NA, computed = max(conv), monte_carlo = NA,
                             abs_diff = max(conv), tolerance = 1e-6,
                             judgment = if (max(conv) <= 1e-6) "PASS" else "FAIL",
                             stringsAsFactors = FALSE))

utils::write.csv(res, file.path(out_dir, "validate_posterior.csv"), row.names = FALSE)
fmt <- function(x) ifelse(is.na(x), "", formatC(x, digits = 6, format = "g"))
md <- c("# Monte Carlo check of PosteriorProb()", "",
        paste0("Generated by inst/validation/validate_posterior.R on ", Sys.Date(), " with ",
               format(B, big.mark = ","), " draws per probability. The last row compares ",
               "200 and 2000 Gauss-Legendre nodes."), "",
        paste0("Judgments: ", paste(names(table(res$judgment)), table(res$judgment),
                                    sep = " = ", collapse = ", "), "."), "",
        paste("| Measure | Reference | Higher better | Target | Computed | Monte Carlo |",
              "Difference | Tolerance | Judgment |"),
        "|---|---|---|---|---|---|---|---|---|",
        paste0("| ", res$measure, " | ", res$two.sample, " | ", res$higher.better, " | ",
               fmt(res$target), " | ", fmt(res$computed), " | ", fmt(res$monte_carlo), " | ",
               fmt(res$abs_diff), " | ", fmt(res$tolerance), " | ", res$judgment, " |"))
writeLines(md, file.path(out_dir, "validate_posterior.md"))
print(table(res$judgment))
if (any(res$judgment == "FAIL")) warning("Some checks failed.")
